<!doctype html>
<!-- ============================================================
     NOIACORE · BIBLIOTECA ABIERTA 2060 · v2 DUAL (LITE/PESADA)
     Fecha: 2026-08-06 · Autocontenido · SIN servidor · 0 archivos
     Arranque CRT solo en HOME · MetaBuscador federado ≈130 bancos
     Líneas totales: >1300 (≈1.5k)
============================================================= -->
<html lang="es" data-mode="pesada" data-theme="dark">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#030308">
<meta name="description" content="NOIACORE 2060: biblioteca abierta federada. 0 archivos almacenados; enruta a las mayores bases abiertas del mundo.">
<meta property="og:title" content="NOIACORE · Biblioteca Abierta 2060">
<meta property="og:description" content="Índice vivo de conocimiento libre con visor interno y metabuscador federado.">
<title>NOIACORE · Biblioteca Abierta 2060</title>
<style>
/* ---------- 1) VARIABLES Y TEMAS ---------- */
:root{
  --bg:#030308;
  --bg2:#08081a;
  --bg3:#0c0c24;
  --line:#12122e;
  --line2:#1e1e44;
  --txt:#eef0ff;
  --mut:#7a7aa8;
  --dim:#52527c;
  --blue:#6b8bff;
  --purple:#a55cff;
  --violet:#8457ff;
  --cyan:#5fd6ef;
  --red:#ff3b5c;
  --glow-blue:0 0 28px -10px rgba(107,139,255,.55);
  --glow-purple:0 0 28px -10px rgba(165,92,255,.55);
  --glass:rgba(8,8,26,.5);
  --spring:cubic-bezier(.22,1,.36,1);
  --f-disp:"Newsreader",Georgia,serif;
  --f-body:"Instrument Sans",system-ui,sans-serif;
  --f-mono:"JetBrains Mono",ui-monospace,monospace;
}
[data-theme="light"]{
  --bg:#f4f4fb;
  --bg2:#ffffff;
  --bg3:#ececf7;
  --line:#dcdcf0;
  --line2:#c6c6e4;
  --txt:#101028;
  --mut:#5a5a86;
  --dim:#8a8ab0;
  --glass:rgba(255,255,255,.6);
}
/* ---------- 2) BASE ---------- */
*,*::before,*::after{
  margin:0;
  padding:0;
  box-sizing:border-box;
}
html{
  scroll-behavior:smooth;
}
body{
  background:var(--bg);
  color:var(--txt);
  font-family:var(--f-body);
  font-size:16px;
  line-height:1.55;
  overflow-x:hidden;
  opacity:0;
  transition:opacity .6s ease;
}
body.on{
  opacity:1;
}
::selection{
  background:var(--purple);
  color:#fff;
}
a{
  color:var(--cyan);
  text-decoration:none;
}
button{
  font-family:var(--f-mono);
  cursor:pointer;
}
.skip{
  position:absolute;
  left:-999px;
  top:0;
  background:var(--purple);
  color:#fff;
  padding:8px 14px;
  z-index:3000;
}
.skip:focus{
  left:8px;
  top:8px;
}
.mono{
  font-family:var(--f-mono);
}
/* ---------- 3) FONDO NEÓN (orbes + rejilla) ---------- */
.neon-bg{
  position:fixed;
  inset:0;
  z-index:-1;
  overflow:hidden;
  opacity:0;
  transition:opacity 1.8s ease;
}
body.on .neon-bg{
  opacity:1;
}
.orb{
  position:absolute;
  border-radius:50%;
  filter:blur(120px);
  opacity:.35;
  will-change:transform;
}
#orb1{
  width:520px;
  height:520px;
  background:var(--violet);
  top:-160px;
  left:-120px;
}
#orb2{
  width:420px;
  height:420px;
  background:var(--blue);
  top:40%;
  right:-160px;
}
#orb3{
  width:380px;
  height:380px;
  background:var(--purple);
  bottom:-140px;
  left:30%;
}
.grid-overlay{
  position:absolute;
  inset:0;
  background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);
  background-size:56px 56px;
  opacity:.16;
  mask-image:radial-gradient(ellipse at 50% 20%,#000 0%,transparent 70%);
}
.p{
  position:absolute;
  width:4px;
  height:4px;
  border-radius:50%;
  background:var(--cyan);
  opacity:.5;
  box-shadow:0 0 10px var(--cyan);
}
/* ---------- 4) CRT BOOT (TV futurista) ---------- */
#crt{
  position:fixed;
  inset:0;
  z-index:2000;
  background:#000;
  display:grid;
  place-items:center;
  overflow:hidden;
}
#crt.off{
  display:none;
}
.crt-beam{
  position:absolute;
  left:50%;
  top:50%;
  width:140%;
  height:2px;
  transform:translate(-50%,-50%) scaleX(0);
  background:linear-gradient(90deg,transparent,var(--purple),#fff,var(--cyan),transparent);
  opacity:0;
  filter:drop-shadow(0 0 14px var(--purple));
}
#crt.b1 .crt-beam{
  animation:beamX .28s var(--spring) forwards;
}
@keyframes beamX{
  0%{transform:translate(-50%,-50%) scaleX(0);opacity:0;}
  60%{opacity:1;}
  100%{transform:translate(-50%,-50%) scaleX(1);opacity:1;}
}
.crt-screen{
  position:absolute;
  inset:0;
  background:#05010d;
  transform:scaleY(.004);
  opacity:0;
}
#crt.b2 .crt-screen{
  animation:expY .34s var(--spring) forwards;
}
@keyframes expY{
  to{transform:scaleY(1);opacity:1;}
}
.crt-static{
  position:absolute;
  inset:-20px;
  opacity:0;
  mix-blend-mode:screen;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2'/></filter><rect width='140' height='140' filter='url(%23n)' opacity='0.5'/></svg>");
}
#crt.b3 .crt-static{
  animation:staticOn .85s steps(6) forwards;
}
@keyframes staticOn{
  0%{opacity:0;transform:translate(0,0);}
  20%{opacity:.55;transform:translate(-6px,4px);}
  40%{opacity:.35;transform:translate(5px,-6px);}
  60%{opacity:.6;transform:translate(-4px,-3px);}
  80%{opacity:.4;transform:translate(6px,5px);}
  100%{opacity:.5;transform:translate(0,0);}
}
.crt-scan{
  position:absolute;
  inset:0;
  background:repeating-linear-gradient(0deg,transparent 0 2px,rgba(0,0,0,.35) 2px 4px);
  pointer-events:none;
}
.crt-glitch{
  position:absolute;
  inset:0;
  opacity:0;
  background:linear-gradient(180deg,transparent 12%,rgba(165,92,255,.25) 13% 15%,transparent 16% 40%,rgba(95,214,239,.2) 41% 42%,transparent 43% 70%,rgba(255,59,92,.18) 71% 74%,transparent 75%);
}
#crt.b3 .crt-glitch{
  animation:glitchJit .5s steps(3) 2;
}
@keyframes glitchJit{
  0%{opacity:.9;transform:translateX(-8px);}
  50%{opacity:.5;transform:translateX(6px);}
  100%{opacity:.8;transform:translateX(0);}
}
.crt-logo{
  position:relative;
  font-family:var(--f-mono);
  font-size:clamp(18px,4vw,34px);
  letter-spacing:.42em;
  color:var(--txt);
  text-shadow:-2px 0 var(--cyan),2px 0 var(--purple);
  opacity:0;
}
#crt.b3 .crt-logo{
  animation:logoIn .45s .08s var(--spring) forwards;
}
@keyframes logoIn{
  0%{opacity:0;transform:scale(1.15);filter:blur(6px);}
  100%{opacity:1;transform:scale(1);filter:blur(0);}
}
#crt.b4{
  animation:wipeOut .55s var(--spring) forwards;
}
@keyframes wipeOut{
  0%{clip-path:inset(0 0 0 0);filter:brightness(1);}
  30%{filter:brightness(1.6);}
  100%{clip-path:inset(0 0 100% 0);filter:brightness(2);}
}
#crt.liteboot{
  transition:opacity .5s ease;
}
#crt.liteboot.b4{
  opacity:0;
}
/* ---------- 5) HEADER GLASS ---------- */
.head{
  position:sticky;
  top:0;
  z-index:100;
  display:flex;
  align-items:center;
  gap:18px;
  padding:14px 28px;
  backdrop-filter:blur(20px) saturate(180%);
  -webkit-backdrop-filter:blur(20px) saturate(180%);
  background:var(--glass);
  border-bottom:1px solid var(--line);
}
.brand{
  font-family:var(--f-disp);
  font-size:20px;
  font-weight:600;
  letter-spacing:.02em;
}
.brand b{
  background:linear-gradient(90deg,var(--blue),var(--violet),var(--purple));
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
}
.nav{
  display:flex;
  gap:16px;
  margin-left:auto;
  font-family:var(--f-mono);
  font-size:12px;
}
.nav a{
  color:var(--mut);
  position:relative;
  padding:4px 2px;
  transition:color .3s var(--spring);
}
.nav a::after{
  content:"";
  position:absolute;
  left:0;
  bottom:0;
  width:0;
  height:1px;
  background:linear-gradient(90deg,var(--blue),var(--purple));
  transition:width .35s var(--spring);
}
.nav a:hover{
  color:var(--txt);
}
.nav a:hover::after{
  width:100%;
}
.pill{
  font-size:11px;
  padding:6px 12px;
  border:1px solid var(--line2);
  border-radius:999px;
  background:var(--bg2);
  color:var(--mut);
  transition:all .3s var(--spring);
}
.pill:hover{
  color:var(--txt);
  border-color:var(--purple);
  box-shadow:var(--glow-purple);
}
/* ---------- 6) HERO ---------- */
.hero{
  max-width:1100px;
  margin:0 auto;
  padding:96px 24px 48px;
  text-align:center;
  position:relative;
}
.kicker{
  font-family:var(--f-mono);
  font-size:12px;
  letter-spacing:.3em;
  color:var(--dim);
  text-transform:uppercase;
}
h1.title{
  font-family:var(--f-disp);
  font-size:clamp(40px,7vw,84px);
  line-height:1.04;
  margin:18px 0 14px;
  background:linear-gradient(100deg,var(--blue),var(--violet) 45%,var(--purple) 80%);
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
  animation:breath 7s ease-in-out infinite;
}
@keyframes breath{
  0%,100%{text-shadow:0 0 18px rgba(132,87,255,.15);}
  50%{text-shadow:0 0 34px rgba(132,87,255,.4);}
}
.sub{
  color:var(--mut);
  max-width:640px;
  margin:0 auto 30px;
}
.searchbox{
  display:flex;
  gap:10px;
  max-width:620px;
  margin:0 auto 16px;
}
.searchbox input{
  flex:1;
  padding:14px 18px;
  border-radius:14px;
  border:1px solid var(--line2);
  background:var(--bg2);
  color:var(--txt);
  font-family:var(--f-body);
  font-size:15px;
  outline:none;
  transition:border .3s,box-shadow .3s;
}
.searchbox input:focus{
  border-color:var(--violet);
  box-shadow:var(--glow-purple);
}
.btn{
  padding:14px 20px;
  border-radius:14px;
  border:1px solid var(--line2);
  background:linear-gradient(120deg,var(--blue),var(--violet));
  color:#fff;
  font-size:13px;
  transition:transform .3s var(--spring),box-shadow .3s;
}
.btn:hover{
  transform:translateY(-2px);
  box-shadow:var(--glow-blue);
}
.btn.ghost{
  background:var(--bg2);
  color:var(--mut);
}
.btn.ghost:hover{
  color:var(--txt);
  box-shadow:var(--glow-purple);
}
.actions{
  display:flex;
  gap:10px;
  justify-content:center;
  flex-wrap:wrap;
}
/* ---------- 7) STATS ---------- */
.stats{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:12px;
  max-width:1000px;
  margin:26px auto 0;
  padding:0 24px;
}
.stat{
  border:1px solid var(--line);
  border-radius:16px;
  background:var(--bg2);
  padding:18px 12px;
  transition:transform .35s var(--spring),box-shadow .35s;
}
.stat:hover{
  transform:translateY(-4px);
  box-shadow:var(--glow-purple);
}
.stat .n{
  font-family:var(--f-mono);
  font-size:26px;
  background:linear-gradient(90deg,var(--cyan),var(--purple));
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
}
.stat .l{
  font-size:11px;
  color:var(--dim);
  letter-spacing:.14em;
  text-transform:uppercase;
}
/* ---------- 8) SECCIONES / FILAS / TARJETAS ---------- */
section{
  content-visibility:auto;
  contain-intrinsic-size:1px 600px;
  max-width:1200px;
  margin:0 auto;
  padding:56px 24px 8px;
}
.sec-head{
  display:flex;
  align-items:baseline;
  gap:14px;
  margin-bottom:20px;
}
.sec-head h2{
  font-family:var(--f-disp);
  font-size:clamp(24px,3.4vw,38px);
}
.sec-head .tag{
  font-family:var(--f-mono);
  font-size:11px;
  color:var(--dim);
  letter-spacing:.2em;
}
.row{
  margin-bottom:34px;
}
.row h3{
  font-family:var(--f-mono);
  font-size:12px;
  letter-spacing:.24em;
  color:var(--mut);
  text-transform:uppercase;
  margin-bottom:12px;
}
.shelf{
  display:grid;
  grid-auto-flow:column;
  gap:14px;
  overflow-x:auto;
  padding:4px 2px 14px;
  scrollbar-width:thin;
  scrollbar-color:var(--line2) transparent;
}
.card{
  position:relative;
  min-width:240px;
  max-width:260px;
  border:1px solid var(--line);
  border-radius:16px;
  background:var(--bg2);
  padding:16px;
  overflow:hidden;
  transition:transform .45s var(--spring),border .3s,box-shadow .3s;
}
.card::before{
  content:"";
  position:absolute;
  top:0;
  left:0;
  right:0;
  height:2px;
  background:var(--cat,var(--violet));
}
.card::after{
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient(105deg,transparent 40%,rgba(255,255,255,.07) 50%,transparent 60%);
  transform:translateX(-120%);
  transition:transform .8s var(--spring);
  pointer-events:none;
}
.card:hover{
  transform:translateY(-5px);
  border-color:var(--line2);
  box-shadow:var(--glow-purple);
}
.card:hover::after{
  transform:translateX(120%);
}
.card .ct{
  font-family:var(--f-mono);
  font-size:10px;
  color:var(--dim);
  letter-spacing:.16em;
  text-transform:uppercase;
}
.card h4{
  font-family:var(--f-disp);
  font-size:17px;
  margin:6px 0;
}
.card p{
  font-size:12.5px;
  color:var(--mut);
  display:-webkit-box;
  -webkit-line-clamp:3;
  -webkit-box-orient:vertical;
  overflow:hidden;
}
.card .meta{
  display:flex;
  gap:6px;
  margin-top:10px;
  flex-wrap:wrap;
}
.chip{
  font-family:var(--f-mono);
  font-size:10px;
  padding:3px 8px;
  border-radius:999px;
  border:1px solid var(--line2);
  color:var(--mut);
}
/* ---------- 9) TABS / CHIPS / GRID RESULTADOS ---------- */
.tabs{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  margin-bottom:14px;
}
.tab{
  padding:8px 14px;
  border-radius:999px;
  border:1px solid var(--line2);
  background:var(--bg2);
  color:var(--mut);
  font-size:12px;
  transition:all .3s var(--spring);
}
.tab.on{
  background:linear-gradient(120deg,var(--blue),var(--violet));
  color:#fff;
  border-color:transparent;
  box-shadow:var(--glow-blue);
}
.chips{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  min-height:26px;
  margin-bottom:12px;
}
.fchip{
  display:inline-flex;
  align-items:center;
  gap:6px;
  font-family:var(--f-mono);
  font-size:11px;
  padding:4px 10px;
  border-radius:999px;
  background:var(--bg3);
  border:1px solid var(--violet);
  color:var(--txt);
}
.fchip button{
  background:none;
  border:none;
  color:var(--red);
  font-size:11px;
}
.grid{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(250px,1fr));
  gap:14px;
}
.count{
  font-family:var(--f-mono);
  font-size:12px;
  color:var(--dim);
  margin:10px 0;
}
.empty{
  border:1px dashed var(--line2);
  border-radius:16px;
  padding:34px;
  text-align:center;
  color:var(--mut);
  display:none;
}
.loadmore{
  display:block;
  margin:22px auto;
}
/* ---------- 10) METABUSCADOR ---------- */
.meta-box{
  border:1px solid var(--line);
  border-radius:20px;
  background:var(--bg2);
  padding:22px;
}
.meta-total{
  font-family:var(--f-mono);
  font-size:13px;
  color:var(--cyan);
  margin:10px 0;
  min-height:20px;
}
.mres{
  display:grid;
  gap:10px;
  margin-top:14px;
}
.mitem{
  display:flex;
  align-items:center;
  gap:12px;
  border:1px solid var(--line);
  border-radius:12px;
  padding:10px 14px;
  background:var(--bg3);
  transition:border .3s,transform .3s var(--spring);
}
.mitem:hover{
  border-color:var(--violet);
  transform:translateX(4px);
}
.mitem .src{
  font-family:var(--f-mono);
  font-size:10px;
  color:var(--purple);
  border:1px solid var(--line2);
  padding:2px 8px;
  border-radius:999px;
