  color:var(--mut);
  transition:all .25s var(--spring);
}
.dl:hover{
  color:var(--txt);
  border-color:var(--cyan);
  box-shadow:0 0 18px -6px var(--cyan);
}
/* ---------- 11) VISOR MODAL ---------- */
#visor{
  position:fixed;
  inset:0;
  z-index:1500;
  display:none;
  align-items:center;
  justify-content:center;
  background:rgba(3,3,8,.7);
  backdrop-filter:blur(14px);
}
#visor.open{
  display:flex;
}
.v-panel{
  width:min(96vw,1100px);
  height:min(88vh,800px);
  background:var(--bg2);
