  border:none;
  background:#000;
}
.v-note{
  padding:26px;
  color:var(--mut);
  font-size:14px;
  display:none;
}
/* ---------- 12) BANDA / FOOTER / TOAST ---------- */
.band{
  text-align:center;
  border:1px solid var(--line);
  border-radius:20px;
  background:linear-gradient(140deg,rgba(107,139,255,.08),rgba(165,92,255,.08));
  padding:34px 22px;
  margin:60px auto;
  max-width:1000px;
}
.foot{
  border-top:1px solid var(--line);
  padding:26px;
  text-align:center;
  color:var(--dim);
  font-family:var(--f-mono);
  font-size:11px;
}
#toast{
  position:fixed;
  bottom:22px;
  left:50%;
  transform:translate(-50%,80px);
  background:var(--bg3);
  border:1px solid var(--violet);
  color:var(--txt);
  border-radius:12px;
  padding:10px 18px;
  font-family:var(--f-mono);
  font-size:12px;
  z-index:2500;
  transition:transform .45s var(--spring);
  box-shadow:var(--glow-purple);
}
#toast.show{
  transform:translate(-50%,0);
}
/* ---------- 13) REVEALS ---------- */
.rv{
  opacity:0;
  transform:translateY(26px);
  transition:opacity .8s var(--spring),transform .8s var(--spring);
}
.rv.in{
  opacity:1;
