<script>
/* ================= NOIACORE 2060 · APP ================= */
"use strict";
/* ---------- utilidades ---------- */
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const enc=q=>encodeURIComponent(q);
const debounce=(fn,ms)=>{let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms);};};
const fmt=n=>new Intl.NumberFormat("es-ES").format(n);
function toast(msg){
  const t=$("#toast");
  t.textContent=msg;
  t.classList.add("show");
  setTimeout(()=>t.classList.remove("show"),2600);
}
function fetchT(url,ms=6000){
  const c=new AbortController();
  const t=setTimeout(()=>c.abort(),ms);
  return fetch(url,{signal:c.signal}).finally(()=>clearTimeout(t));
}
/* ---------- preferencias (solo ajustes, nunca contenido) ---------- */
const LS={mode:"ncore_mode",theme:"ncore_theme",sound:"ncore_sound"};
const reduced=matchMedia("(prefers-reduced-motion: reduce)").matches;
const conn=navigator.connection||{};
const weak=(navigator.deviceMemory&&navigator.deviceMemory<=2)
  ||(navigator.hardwareConcurrency&&navigator.hardwareConcurrency<=2)
  ||conn.saveData
  ||["slow-2g","2g","3g"].includes(conn.effectiveType);
let mode=localStorage.getItem(LS.mode)
  ||(weak||reduced?"lite":"pesada");
let theme=localStorage.getItem(LS.theme)||"dark";
let sound=localStorage.getItem(LS.sound)==="1";
function applyPrefs(){
  document.documentElement.dataset.mode=mode;
  document.documentElement.dataset.theme=theme;
  $("#btn-mode").textContent="MODO:"+mode.toUpperCase();
  $("#btn-sound").textContent="SONIDO:"+(sound?"ON":"OFF");
}
/* ---------- inyección condicional (lite = 0 pesos extra) ---------- */
function loadCSS(href){
  const l=document.createElement("link");
  l.rel="stylesheet";
  l.href=href;
  document.head.appendChild(l);
}
function loadJS(src){
  return new Promise((res,rej)=>{
    const s=document.createElement("script");
    s.src=src;
    s.onload=res;
    s.onerror=rej;
    document.head.appendChild(s);
  });
}
const FONTS="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,600&family=Instrument+Sans:wght@400;500&family=JetBrains+Mono:wght@400;600&display=swap";
const GSAP="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js";
const ST="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js";
/* ---------- sintetizador de sonido (WebAudio, sin assets) ---------- */
let AC=null;
function audio(){
  if(!sound)return null;
  if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();
  if(AC.state==="suspended")AC.resume();
  return AC;
}
function sClick(){
  const a=audio();if(!a)return;
  const o=a.createOscillator(),g=a.createGain();
  o.type="square";o.frequency.value=1400;
  g.gain.setValueAtTime(.08,a.currentTime);
  g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+.08);
  o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+.09);
}
function sHum(){
  const a=audio();if(!a)return;
  const o=a.createOscillator(),g=a.createGain();
  o.type="sawtooth";
  o.frequency.setValueAtTime(46,a.currentTime);
  o.frequency.exponentialRampToValueAtTime(120,a.currentTime+.5);
  g.gain.setValueAtTime(.0001,a.currentTime);
  g.gain.exponentialRampToValueAtTime(.06,a.currentTime+.12);
  g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+.7);
  o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+.75);
}
function sCrackle(){
  const a=audio();if(!a)return;
  const len=a.sampleRate*.5;
  const buf=a.createBuffer(1,len,a.sampleRate);
  const d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/len,2)*(Math.random()<.2?1:.25);
  const src=a.createBufferSource();src.buffer=buf;
  const f=a.createBiquadFilter();f.type="bandpass";f.frequency.value=1900;
  const g=a.createGain();g.gain.value=.12;
  src.connect(f).connect(g).connect(a.destination);src.start();
}
/* ---------- CRT BOOT (solo en home) ---------- */
const crt=$("#crt");
const isHome=!location.hash||location.hash==="#home"||location.hash==="#/";
let booted=false;
function runBoot(){
  if(booted)return;
  booted=true;
  if(!isHome||reduced){
    crt.classList.add("off");
    document.body.classList.add("on");
    return;
  }
  if(mode==="lite"){
    crt.classList.add("liteboot","b1");
    setTimeout(()=>crt.classList.add("b4"),420);
    setTimeout(()=>{crt.classList.add("off");document.body.classList.add("on");},950);
    return;
  }
  sClick();
  setTimeout(()=>crt.classList.add("b1"),80);
  setTimeout(()=>{crt.classList.add("b2");sHum();},380);
  setTimeout(()=>{crt.classList.add("b3");sCrackle();},760);
  setTimeout(()=>crt.classList.add("b4"),1680);
  setTimeout(()=>{crt.classList.add("off");document.body.classList.add("on");},2300);
}
crt.addEventListener("click",()=>{
  crt.classList.add("off");
  document.body.classList.add("on");
});
