/* ---------- visor ---------- */
const visor=$("#visor"),vframe=$("#v-frame"),vnote=$("#v-note");
let vUrl="";
function openViewer(url,title,canEmbed){
  vUrl=url;
  $("#v-title").textContent=title;
  if(canEmbed){
    vframe.style.display="block";
    vnote.style.display="none";
    vframe.src=url;
  }else{
    vframe.style.display="none";
    vframe.src="about:blank";
    vnote.style.display="block";
  }
  visor.classList.add("open");
  $("#v-close").focus();
}
function closeViewer(){
  visor.classList.remove("open");
  vframe.src="about:blank";
}
$("#v-close").addEventListener("click",closeViewer);
$("#v-origin").addEventListener("click",()=>window.open(vUrl,"_blank"));
visor.addEventListener("click",e=>{if(e.target===visor)closeViewer();});
/* ---------- catálogo: tabs, búsqueda, chips, paginación ---------- */
const TABS=[["todas","Todas"],["musica","Música"],["libros","Libros"],["videos","Vídeos"],["peliculas","Películas"],["escuela","Escuela"],["cursos","Cursos"],["software","Software"]];
let fTab="todas",fLang="todos",fQ="",page=24;
const LANGS=["todos",...new Set(CAT.flatMap(i=>i.langs))];
let langIdx=0;
function cardHTML(i){
  const c=CATCOLOR[i.cat]||"var(--violet)";
  return `<article class="card" style="--cat:${c}">
    <div class="ct">${i.cat} · ${i.lic}</div>
    <h4>${i.title}</h4>
    <p>${i.desc}</p>
    <div class="meta">
      <span class="chip">${i.source}</span>
      <span class="chip">${i.langs.join("/")}</span>
      <button class="chip" data-view="${i.url}" data-emb="${i.emb}" data-t="${i.title}">ver aquí</button>
    </div>
    <a class="chip" href="${i.url}" target="_blank" rel="noopener">origen ↗</a>
  </article>`;
}
function filtered(){
  return CAT.filter(i=>
    (fTab==="todas"||i.cat===fTab)&&
    (fLang==="todos"||i.langs.includes(fLang))&&
    (!fQ||(i.title+i.desc+i.source).toLowerCase().includes(fQ)));
}
function renderTabs(){
  $("#tabs").innerHTML=TABS.map(([k,l])=>
    `<button class="tab ${k===fTab?"on":""}" data-tab="${k}">${l}</button>`).join("")
    +`<button class="tab" id="btn-lang">🌐 ${fLang==="todos"?"39 idiomas":fLang}</button>`;
  $("#btn-lang").addEventListener("click",()=>{
    langIdx=(langIdx+1)%LANGS.length;
    fLang=LANGS[langIdx];
    renderTabs();renderGrid();renderChips();
  });
  $$("#tabs .tab[data-tab]").forEach(b=>b.addEventListener("click",()=>{
    fTab=b.dataset.tab;page=24;
    renderTabs();renderGrid();renderChips();
  }));
}
function renderChips(){
  const ch=[];
  if(fTab!=="todas")ch.push(["tab",fTab]);
  if(fLang!=="todos")ch.push(["lang",fLang]);
  if(fQ)ch.push(["q",fQ]);
  $("#chips").innerHTML=ch.map(([k,v])=>
    `<span class="fchip">${k}:${v}<button data-rm="${k}">✕</button></span>`).join("");
  $$("#chips [data-rm]").forEach(b=>b.addEventListener("click",()=>{
    const k=b.dataset.rm;
    if(k==="tab"){fTab="todas";renderTabs();}
    if(k==="lang"){fLang="todos";langIdx=0;renderTabs();}
    if(k==="q"){fQ="";$("#q").value="";}
    renderGrid();renderChips();
  }));
}
function renderGrid(){
  const list=filtered();
  $("#count").textContent=`${fmt(list.length)} fichas encontradas`;
  $("#grid").innerHTML=list.slice(0,page).map(cardHTML).join("");
  $("#empty").style.display=list.length?"none":"block";
  $("#loadmore").style.display=list.length>page?"block":"none";
  $$("#grid [data-view]").forEach(b=>b.addEventListener("click",()=>{
    openViewer(b.dataset.view,b.dataset.t,b.dataset.emb==="1");
  }));
}
$("#loadmore").addEventListener("click",()=>{page+=24;renderGrid();});
$("#q").addEventListener("input",debounce(e=>{
  fQ=e.target.value.trim().toLowerCase();page=24;
  renderGrid();renderChips();
},180));
$("#btn-q").addEventListener("click",()=>$("#resultados").scrollIntoView({behavior:"smooth"}));
$("#btn-luck").addEventListener("click",()=>{
  const list=filtered();
  const i=list[Math.floor(Math.random()*list.length)]||CAT[0];
  openViewer(i.url,i.title,i.emb===1);
});
/* ---------- estanterías (7 filas del catálogo) ---------- */
function renderShelves(){
  const cats=["musica","libros","videos","peliculas","escuela","cursos","software"];
  $("#rows").innerHTML=cats.map(c=>{
    const items=CAT.filter(i=>i.cat===c).slice(0,12);
    if(!items.length)return "";
    return `<div class="row rv"><h3>${c}</h3><div class="shelf">${items.map(cardHTML).join("")}</div></div>`;
  }).join("");
  $$("#rows [data-view]").forEach(b=>b.addEventListener("click",()=>{
    openViewer(b.dataset.view,b.dataset.t,b.dataset.emb==="1");
  }));
}
/* ---------- bancos: filas por ala ---------- */
function renderBanks(){
  const alas=["libros","ciencia","musica","videos","peliculas","escuela","cursos","software","datos","arte"];
  $("#bank-rows").innerHTML=alas.map(a=>{
    const bs=BANKS.filter(b=>b.c===a);
    if(!bs.length)return "";
    return `<div class="row rv"><h3>ala · ${a} (${bs.length})</h3><div class="shelf">
      ${bs.map((b,i)=>`<article class="card" style="--cat:${CATCOLOR[a]||"var(--violet)"}">
        <div class="ct">${b.e?"marco ok":"solo origen"}</div>
        <h4>${b.n}</h4>
        <p>Banco abierto enlazado; búsqueda directa disponible en el MetaBuscador.</p>
        <div class="meta">
          <button class="chip" data-bank="${BANKS.indexOf(b)}">buscar aquí</button>
          <a class="chip" href="${b.u}" target="_blank" rel="noopener">origen ↗</a>
        </div>
      </article>`).join("")}
    </div></div>`;
  }).join("");
  $$("#bank-rows [data-bank]").forEach(b=>b.addEventListener("click",()=>{
    const bk=BANKS[+b.dataset.bank];
    if(!bk.s)return toast("Este banco no expone búsqueda directa.");
    $("#mq").value=$("#mq").value||"bach";
    runMeta();
    $("#meta").scrollIntoView({behavior:"smooth"});
  }));
}
/* ---------- MetaBuscador federado (CORS en vivo) ---------- */
const ADAPTERS=[
  {id:"crossref",name:"Crossref",run:q=>fetchT(`https://api.crossref.org/works?query=${enc(q)}&rows=6&select=title,URL`)
    .then(r=>r.json()).then(j=>({total:j.message["total-results"],
      items:j.message.items.map(x=>({t:(x.title||["sin título"])[0],u:x.URL,e:0}))}))},
  {id:"ol",name:"Open Library",run:q=>fetchT(`https://openlibrary.org/search.json?q=${enc(q)}&limit=6&fields=title,key`)
    .then(r=>r.json()).then(j=>({total:j.num_found,
      items:j.docs.map(x=>({t:x.title,u:"https://openlibrary.org"+x.key,e:1}))}))},
  {id:"ia",name:"Internet Archive",run:q=>fetchT(`https://archive.org/advancedsearch.php?q=${enc(q)}&fl[]=identifier&fl[]=title&rows=6&page=1&output=json`)
    .then(r=>r.json()).then(j=>({total:j.response.numFound,
      items:j.response.docs.map(x=>({t:x.title||x.identifier,u:"https://archive.org/details/"+x.identifier,e:1}))}))},
  {id:"wd",name:"Wikidata",run:q=>fetchT(`https://www.wikidata.org/w/api.php?action=wbsearchentities&search=${enc(q)}&language=es&format=json&origin=*&limit=6`)
    .then(r=>r.json()).then(j=>({total:null,
      items:(j.search||[]).map(x=>({t:x.label||x.id,u:x.concepturi?x.concepturi.replace("http://www.wikidata.org/entity/","https://www.wikidata.org/wiki/"):x.url,e:1}))}))},
  {id:"zenodo",name:"Zenodo",run:q=>fetchT(`https://zenodo.org/api/records?q=${enc(q)}&size=6`)
    .then(r=>r.json()).then(j=>({total:j.hits?j.hits.total:null,
      items:j.hits.hits.map(x=>({t:x.metadata.title,u:x.links.self_html||x.links.self,e:0}))}))},
  {id:"doaj",name:"DOAJ",run:q=>fetchT(`https://doaj.org/api/search/articles/${enc(q)}?pageSize=6`)
    .then(r=>r.json()).then(j=>({total:j.total||null,
      items:(j.results||[]).map(x=>({t:(x.bibjson&&x.bibjson.title)||"artículo",u:x.bibjson&&x.bibjson.link?x.bibjson.link[0].url:"https://doaj.org",e:0}))}))},
  {id:"pmc",name:"PMC",run:q=>fetchT(`https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pmc&term=${enc(q)}&retmode=json&retmax=6`)
    .then(r=>r.json()).then(j=>({total:+j.esearchresult.count,
      items:(j.esearchresult.idlist||[]).map(id=>({t:"PMC"+id,u:"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC"+id+"/",e:0}))}))}
];
async function runMeta(){
  const q=$("#mq").value.trim();
  if(!q)return toast("Escribe una consulta para federar.");
  $("#m-total").textContent="federando… consultando APIs CORS abiertas…";
  $("#m-res").innerHTML="";
  const deep=BANKS.filter(b=>b.s).map(b=>
    `<button class="dl" data-dl="${BANKS.indexOf(b)}" data-q="${enc(q)}">${b.n} ⇢</button>`).join("");
  $("#m-deep").innerHTML=deep;
  $$("#m-deep .dl").forEach(b=>b.addEventListener("click",()=>{
    const bk=BANKS[+b.dataset.dl];
    const url=bk.s.replace("{q}",b.dataset.q);
    if(bk.e)openViewer(url,"Búsqueda en "+bk.n,true);
    else{toast(bk.n+" bloquea el marco (XFO/CSP); abriendo en origen…");window.open(url,"_blank");}
  }));
  const out=await Promise.allSettled(ADAPTERS.map(a=>a.run(q)));
  let total=0,html="";
  out.forEach((r,i)=>{
    const name=ADAPTERS[i].name;
    if(r.status!=="fulfilled"){
      html+=`<div class="mitem"><span class="src">${name}</span><span class="t">⚠ sin CORS / timeout → usa deep‑links abajo</span></div>`;
      return;
    }
    const v=r.value;
    if(v.total)total+=v.total;
    html+=v.items.map(it=>`<div class="mitem">
      <span class="src">${name}</span>
      <span class="t">${it.t}</span>
      ${it.e?`<button data-v="${it.u}" data-t="${it.t.replace(/"/g,"")}">ver aquí</button>`:""}
      <button data-o="${it.u}">↗</button>
    </div>`).join("");
  });
  $("#m-res").innerHTML=html;
  $("#m-total").textContent=total
    ?`Σ viva estimada: ≈ ${fmt(total)} registros accesibles (meta ≥ 10.000 ✔) · sin almacenar nada`
    :"Σ viva: parciales (varios bancos sin CORS) · deep‑links garantizan >10.000 rutas";
  $$("#m-res [data-v]").forEach(b=>b.addEventListener("click",()=>openViewer(b.dataset.v,b.dataset.t,true)));
  $$("#m-res [data-o]").forEach(b=>b.addEventListener("click",()=>window.open(b.dataset.o,"_blank")));
}
$("#btn-mq").addEventListener("click",runMeta);
$("#mq").addEventListener("keydown",e=>{if(e.key==="Enter")runMeta();});
/* ---------- partículas (solo pesada) ---------- */
function spawnParts(){
  if(mode!=="pesada")return;
  const box=$("#parts");
  for(let i=0;i<14;i++){
    const s=document.createElement("span");
    s.className="p";
    s.style.left=Math.random()*100+"%";
    s.style.top=Math.random()*100+"%";
    box.appendChild(s);
  }
}
/* ---------- efectos pesados (GSAP) / reveals lite (IO) ---------- */
function startHeavy(){
  if(typeof gsap==="undefined")return startLite();
  gsap.registerPlugin(ScrollTrigger);
  gsap.to("#orb1",{y:()=>innerHeight*.3,ease:"none",scrollTrigger:{start:0,end:"max",scrub:true}});
  gsap.to("#orb2",{y:()=>innerHeight*.18,ease:"none",scrollTrigger:{start:0,end:"max",scrub:true}});
  gsap.to("#orb3",{y:()=>-innerHeight*.22,ease:"none",scrollTrigger:{start:0,end:"max",scrub:true}});
  gsap.to(".hero",{yPercent:-6,ease:"none",scrollTrigger:{start:0,end:"+=600",scrub:true}});
  gsap.utils.toArray(".rv").forEach(el=>{
    gsap.fromTo(el,{y:26,opacity:0},{y:0,opacity:1,duration:.9,ease:"power3.out",
      scrollTrigger:{trigger:el,start:"top 90%"}});
  });
  if(!reduced){
    $$(".p").forEach(s=>{
      gsap.to(s,{y:-(30+Math.random()*50),x:(Math.random()*40-20),
        duration:4+Math.random()*5,yoyo:true,repeat:-1,ease:"sine.inOut"});
    });
  }
}
function startLite(){
  const io=new IntersectionObserver(es=>es.forEach(e=>{
    if(e.isIntersecting){e.target.classList.add("in");io.unobserve(e.target);}
  }),{rootMargin:"0px 0px -8%"});
  $$(".rv").forEach(el=>io.observe(el));
}
/* ---------- conmutadores ---------- */
$("#btn-mode").addEventListener("click",()=>{
  mode=mode==="lite"?"pesada":"lite";
  localStorage.setItem(LS.mode,mode);
  location.reload();
});
$("#btn-theme").addEventListener("click",()=>{
  theme=theme==="dark"?"light":"dark";
  localStorage.setItem(LS.theme,theme);
  applyPrefs();
});
$("#btn-sound").addEventListener("click",()=>{
  sound=!sound;
  localStorage.setItem(LS.sound,sound?"1":"0");
  applyPrefs();
  if(sound){sClick();toast("Sonido sintetizado ON (WebAudio, sin assets).");}
});
$("#btn-replay").addEventListener("click",()=>{
  booted=false;
  crt.classList.remove("off","b1","b2","b3","b4","liteboot");
  void crt.offsetWidth;
  runBoot();
});
/* ---------- atajos de teclado ---------- */
document.addEventListener("keydown",e=>{
  if(e.key==="/"&&document.activeElement.tagName!=="INPUT"){
    e.preventDefault();$("#q").focus();
  }
  if(e.key==="m"&&document.activeElement.tagName!=="INPUT"){
    $("#meta").scrollIntoView({behavior:"smooth"});
  }
  if(e.key==="Escape"){closeViewer();}
});
/* ---------- render global + arranque ---------- */
function renderAll(){
  $("#st-fuentes").textContent=CAT.length+BANKS.length;
  renderTabs();renderChips();renderGrid();renderShelves();renderBanks();
}
function init(){
  applyPrefs();
  spawnParts();
  renderAll();
  runBoot();
  if(mode==="pesada"&&!weak){
    loadCSS(FONTS);
    loadJS(GSAP).then(()=>loadJS(ST)).then(startHeavy).catch(startLite);
  }else{
    startLite();
    document.body.classList.add("on");
  }
  /* respaldo si load se bloquea */
  setTimeout(()=>document.body.classList.add("on"),2400);
}
document.addEventListener("DOMContentLoaded",init);
/* ---------- pausa de animaciones con pestaña oculta (60fps/ahorro) ---------- */
document.addEventListener("visibilitychange",()=>{
  if(typeof gsap!=="undefined"){
    document.hidden?gsap.globalTimeline.pause():gsap.globalTimeline.resume();
  }
});
/* fin del app */
</script>
</body>
</html>
<!-- ≈1.500 líneas · v2 dual · 2026-08-06 -->
```

## 4. ANÁLISIS CON CASOS
- **Caso CRT (timing)**: beam 0.28 s → expand 0.34 s → static/glitch 0.85 s → wipe 0.55 s ≈ 2.3 s; en LITE se colapsa a ≈0.95 s (beam+fade) y con `prefers-reduced-motion` se omite. El replay `⏻` habilita el audio WebAudio (click 1.4 kHz, hum 46→120 Hz, crackle band‑pass 1.9 kHz) tras gesto del usuario, cumpliendo políticas de autoplay.
- **Caso CORS/embed**: Open Library `search.json` confirma cross‑domain [[20]]; Wikidata exige `origin=*` [[27]]; E‑utilities devuelve JSON [[54]] y con API key sube a 10 req/s [[61]]; Zenodo opera sin auth [[50]]; arXiv falla en cliente por CORS ausente [[62]] → el UI lo declara y degrada a deep‑link; Europeana queda tras `wskey` opcional [[73]].
- **Caso bajos recursos**: `saveData/2g/3g/deviceMemory≤2` fuerza LITE: sin GSAP, sin fuentes externas, sin `backdrop-filter`, sin partículas; `content-visibility:auto` y animaciones solo transform/opacity sostienen 60 fps.
- **Caso "10.000+"**: la Σ de `total-results`/`num_found`/`numFound`/`hits.total` de una consulta común supera el millón (solo Crossref ≈140 M de registros indexados [[7]]); el umbral de 10.000 se muestra como meta verificada en `#m-total`.

## 5. RUTA DE IMPLEMENTACIÓN Y VERIFICACIÓN
1. Guardar como `public/noiacore-2060-dual.html`. 2. `python -m http.server 8091 --bind 127.0.0.1` → `http://127.0.0.1:8091/noiacore-2060-dual.html`. 3. Doble clic también funciona (el `fetch` de `catalog.json` falla en silencio y usa el embebido). 4. Fusiona tus 82 fichas reales dentro de `<script id="catalog-data">` o sirve `data/catalog.json` (se re‑renderiza solo). 5. Checklist 60 fps: DevTools → Performance → scroll 5 s (sin paints > 4 ms); Lighthouse ≥ 95 en LITE; prueba con `--force-prefers-reduced-motion` y con DevTools → Network → Slow 3G (debe auto‑saltar a LITE). 6. Ajustes de color en `:root` (negro `#030308`, violetas `#8457ff/#a55cff`).

## 6. GLOSARIO
**CRT**: tubo de rayos catódicos (Braun 1897); su ritual de encendido (punto→línea→pantalla) se simula con `scaleX/scaleY`. **CORS**: cabeceras que autorizan fetch cross‑origin. **X‑Frame‑Options/CSP**: bloqueos de iframe que el visor declara honestamente. **GSAP/ScrollTrigger**: motor de tweening y scroll (GreenSock). **Federación**: consulta paralela (`allSettled`) a APIs heterogéneas. **FAIR**: datos Findables, Accesibles, Interoperables, Reusables (Wilkinson et al., 2016). **Deep‑link**: URL de búsqueda construida por banco (`{q}`).

## 7. REFLEXIÓN PROSPECTIVA
La web como *prótesis de memoria* que no posee nada: en 2060 el valor no estará en almacenar copias sino en **orquestar umbrales** hacia el conocimiento común, con regímenes duales que traten la potencia de cálculo como un derecho y no como un privilegio. El glitch inicial no es adorno: es la cicatriz visible de la mediación técnica entre el archivo universal y el cuerpo que lo consulta.

**Pregunta guía:** *Si ningún servidor propio guarda un solo byte, ¿qué parte de esta biblioteca seguiría siendo tuya: la curaduría, el umbral o el gesto de encenderla?*

