<!DOCTYPE html>
<html lang="es" data-mode="max" data-theme="oled">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
<meta name="theme-color" content="#020205">
<meta name="description" content="NOIACORE MAX 2060: Plataforma de streaming cinematográfico para conocimiento abierto. Interfaz de élite, motor de inferencia local y federación de datos globales.">
<title>NOIACORE MAX · 2060</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Newsreader:ital,opsz,wght@0,6..72,300;0,6..72,600;1,6..72,400&family=Instrument+Sans:wght@400;500;600&family=JetBrains+Mono:wght@400;500;700&display=swap" rel="stylesheet">
<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>
<style>
:root {
  --bg-oled: #020205;
  --bg-deep: #05050f;
  --bg-surface: #0a0a14;
  --bg-elevated: #12121f;
  --line-subtle: rgba(255, 255, 255, 0.06);
  --line-active: rgba(255, 255, 255, 0.15);
  --txt-primary: #ffffff;
  --txt-secondary: #a0a0b8;
  --txt-muted: #5a5a70;
  --neon-violet: #7c3aed;
  --neon-blue: #3b82f6;
  --neon-cyan: #06b6d4;
  --neon-pink: #ec4899;
  --glow-violet: 124, 58, 237;
  --glow-blue: 59, 130, 246;
  --glow-cyan: 6, 182, 212;
  --font-display: 'Newsreader', Georgia, serif;
  --font-body: 'Instrument Sans', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --header-h: 80px;
  --header-h-scrolled: 60px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: var(--neon-violet) var(--bg-deep);
}

body {
  background: var(--bg-oled);
  color: var(--txt-primary);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  overflow-x: hidden;
  opacity: 0;
  transition: opacity 0.8s ease;
}

body.ready { opacity: 1; }

::selection { background: var(--neon-violet); color: #fff; }

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
img, svg { display: block; max-width: 100%; }

.skip-link {
  position: absolute;
  top: -100px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--neon-violet);
  color: #fff;
  padding: 12px 24px;
  border-radius: 8px;
  z-index: 9999;
  transition: top 0.3s;
}
.skip-link:focus { top: 20px; }

/* =========================================
   1. CRT BOOT SEQUENCE
   ========================================= */
#crt-boot {
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: #000;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  perspective: 1000px;
}

#crt-boot.off { display: none; }

.crt-tube {
  width: 100%;
  height: 100%;
  position: relative;
  transform-origin: center;
}

.crt-beam {
  position: absolute;
  top: 50%;
  left: 0;
  width: 100%;
  height: 2px;
  background: #fff;
  box-shadow: 0 0 20px 5px #fff, 0 0 60px 10px var(--neon-violet);
  transform: translateY(-50%) scaleX(0);
  opacity: 0;
}

.crt-expand {
  position: absolute;
  inset: 0;
  background: var(--bg-oled);
  transform: scaleY(0.005);
  opacity: 0;
}

.crt-static {
  position: absolute;
  inset: -50px;
  opacity: 0;
  mix-blend-mode: screen;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.6'/%3E%3C/svg%3E");
}

.crt-scanlines {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.4) 2px,
    rgba(0, 0, 0, 0.4) 4px
  );
  pointer-events: none;
  opacity: 0;
}

.crt-logo {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-mono);
  font-size: clamp(24px, 5vw, 48px);
  font-weight: 700;
  letter-spacing: 0.2em;
  color: #fff;
  text-shadow: 
    -2px 0 var(--neon-cyan),
    2px 0 var(--neon-pink),
    0 0 20px var(--neon-violet);
  opacity: 0;
  white-space: nowrap;
}

/* =========================================
   2. BACKGROUND & ATMOSPHERE
   ========================================= */
.atmosphere {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  overflow: hidden;
}

.orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(120px);
  opacity: 0.4;
  will-change: transform;
}

.orb-1 { width: 600px; height: 600px; background: var(--neon-violet); top: -200px; left: -200px; }
.orb-2 { width: 500px; height: 500px; background: var(--neon-blue); top: 40%; right: -150px; }
.orb-3 { width: 450px; height: 450px; background: var(--neon-cyan); bottom: -100px; left: 30%; opacity: 0.2; }

.grid-overlay {
  position: absolute;
  inset: 0;
  background-image: 
    linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse at 50% 0%, #000 20%, transparent 70%);
}

/* =========================================
   3. SMART HEADER (Glassmorphism)
   ========================================= */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-h);
  z-index: 1000;
  display: flex;
  align-items: center;
  padding: 0 40px;
  transition: all 0.4s var(--ease-out-expo);
  background: transparent;
}

.header.scrolled {
  height: var(--header-h-scrolled);
  background: rgba(2, 2, 5, 0.85);
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
  border-bottom: 1px solid var(--line-subtle);
}

.logo {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 600;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-mark {
  width: 32px;
  height: 32px;
  background: linear-gradient(135deg, var(--neon-violet), var(--neon-cyan));
  border-radius: 8px;
  position: relative;
}
.logo-mark::after {
  content: '';
  position: absolute;
  inset: 4px;
  background: var(--bg-oled);
  border-radius: 4px;
}

.nav-main {
  display: flex;
  gap: 32px;
  margin-left: 60px;
}

.nav-link {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--txt-secondary);
  position: relative;
  padding: 8px 0;
  transition: color 0.3s;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--neon-violet), var(--neon-cyan));
  transition: width 0.4s var(--ease-out-expo);
}

.nav-link:hover, .nav-link.active { color: var(--txt-primary); }
.nav-link:hover::after, .nav-link.active::after { width: 100%; }

.header-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 16px;
}

.btn-glass {
  padding: 8px 16px;
  border-radius: 99px;
  border: 1px solid var(--line-active);
  background: rgba(255, 255, 255, 0.05);
  font-size: 13px;
  font-weight: 500;
  transition: all 0.3s;
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-glass:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: var(--neon-violet);
  box-shadow: 0 0 20px -5px rgba(var(--glow-violet), 0.5);
}

/* =========================================
   4. CINEMATIC HERO
   ========================================= */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 120px 40px 80px;
  position: relative;
}

.hero-kicker {
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--neon-cyan);
  margin-bottom: 24px;
  opacity: 0;
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(48px, 8vw, 120px);
  font-weight: 300;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin-bottom: 32px;
  max-width: 1000px;
}

.hero-title .word {
  display: inline-block;
  overflow: hidden;
  vertical-align: top;
  margin-right: 0.2em;
}

.hero-title .char {
  display: inline-block;
  transform: translateY(100%);
  opacity: 0;
}

.hero-title em {
  font-style: italic;
  font-weight: 600;
  background: linear-gradient(135deg, var(--neon-violet) 0%, var(--neon-cyan) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hero-sub {
  font-size: clamp(16px, 2vw, 20px);
  color: var(--txt-secondary);
  max-width: 600px;
  margin-bottom: 48px;
  opacity: 0;
}

.hero-search {
  display: flex;
  width: 100%;
  max-width: 640px;
  background: var(--bg-surface);
  border: 1px solid var(--line-active);
  border-radius: 16px;
  padding: 8px;
  transition: all 0.4s var(--ease-out-expo);
  opacity: 0;
}

.hero-search:focus-within {
  border-color: var(--neon-violet);
  box-shadow: 0 0 40px -10px rgba(var(--glow-violet), 0.4);
  transform: translateY(-2px);
}

.hero-search input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--txt-primary);
  font-size: 16px;
  padding: 12px 20px;
  font-family: var(--font-body);
}

.hero-search input::placeholder { color: var(--txt-muted); }

.btn-primary {
  padding: 12px 32px;
  background: linear-gradient(135deg, var(--neon-violet), var(--neon-blue));
  color: #fff;
  font-weight: 600;
  border-radius: 12px;
  font-size: 15px;
