}

.ai-terminal {
  background: var(--bg-deep);
  border: 1px solid var(--line-subtle);
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 40px 80px -20px rgba(0, 0, 0, 0.8);
}

.term-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 24px;
  border-bottom: 1px solid var(--line-subtle);
  background: rgba(255, 255, 255, 0.02);
}

.term-dots { display: flex; gap: 8px; }
.term-dot { width: 12px; height: 12px; border-radius: 50%; }
.term-dot.r { background: #ff5f56; }
.term-dot.y { background: #ffbd2e; }
.term-dot.g { background: #27c93f; }

.term-title {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--txt-muted);
  margin-left: 12px;
}

.term-body {
  padding: 32px;
  min-height: 200px;
  font-family: var(--font-mono);
  font-size: 14px;
  line-height: 1.8;
  color: var(--txt-secondary);
}

.term-prompt { color: var(--neon-cyan); }
.term-cursor {
  display: inline-block;
  width: 8px;
  height: 16px;
  background: var(--neon-cyan);
  vertical-align: middle;
  margin-left: 4px;
  animation: blink 1s step-end infinite;
}
@keyframes blink { 50% { opacity: 0; } }

.term-output { margin-top: 24px; white-space: pre-wrap; }
.term-output .highlight { color: var(--neon-violet); font-weight: 500; }

.term-results {
  padding: 0 32px 32px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 24px;
  opacity: 0;
  transform: translateY(20px);
  transition: all 0.6s var(--ease-out-expo);
}

.term-results.visible {
  opacity: 1;
  transform: translateY(0);
}

/* =========================================
   6. STREAMING CAROUSELS (HBO/Netflix Style)
   ========================================= */
.section-stream {
  padding: 80px 0;
  position: relative;
}

.stream-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 0 40px;
  margin-bottom: 24px;
}

.stream-title {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 600;
}

.stream-nav {
  display: flex;
  gap: 12px;
}

.stream-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--line-active);
