  align-items: center;
  justify-content: center;
  transition: all 0.3s;
}

.stream-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: var(--neon-violet);
}

.stream-track {
  display: flex;
  gap: 24px;
  padding: 20px 40px 60px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.stream-track::-webkit-scrollbar { display: none; }

.stream-card {
  flex: 0 0 280px;
  aspect-ratio: 2/3;
  border-radius: 12px;
  overflow: hidden;
  position: relative;
  scroll-snap-align: start;
  transition: transform 0.5s var(--ease-out-expo), box-shadow 0.5s;
  cursor: pointer;
  background: var(--bg-surface);
}

.stream-card:hover {
  transform: scale(1.08) translateY(-10px);
  z-index: 10;
  box-shadow: 0 30px 60px -15px rgba(var(--glow-violet), 0.5);
}

.card-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  transition: transform 0.8s var(--ease-out-expo);
}

.stream-card:hover .card-bg { transform: scale(1.1); }

.card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(2,2,5,0.95) 0%, rgba(2,2,5,0.6) 40%, transparent 100%);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 24px;
  opacity: 0;
  transition: opacity 0.4s;
}

.stream-card:hover .card-overlay { opacity: 1; }

.card-cat {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--neon-cyan);
  margin-bottom: 8px;
}

.card-title {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 600;
  line-height: 1.2;
  margin-bottom: 12px;
}

.card-desc {
  font-size: 13px;
  color: var(--txt-secondary);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 16px;
}

.card-actions {
  display: flex;
  gap: 12px;
}

.btn-play {
  flex: 1;
  padding: 10px;
  background: #fff;
  color: #000;
  border-radius: 6px;
  font-weight: 600;
  font-size: 13px;
