.btn-info {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.btn-info:hover { border-color: #fff; background: rgba(255,255,255,0.1); }

/* =========================================
   7. FILTERABLE CATALOG GRID
   ========================================= */
.section-catalog {
  padding: 120px 40px;
  max-width: 1400px;
  margin: 0 auto;
}

.catalog-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 40px;
  overflow-x: auto;
  padding-bottom: 16px;
  scrollbar-width: none;
}
.catalog-tabs::-webkit-scrollbar { display: none; }

.cat-tab {
  padding: 10px 24px;
  border-radius: 99px;
  border: 1px solid var(--line-subtle);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: all 0.3s;
  color: var(--txt-secondary);
}

.cat-tab:hover { border-color: var(--line-active); color: var(--txt-primary); }

.cat-tab.active {
  background: linear-gradient(135deg, var(--neon-violet), var(--neon-blue));
  border-color: transparent;
  color: #fff;
  box-shadow: 0 10px 30px -10px rgba(var(--glow-violet), 0.6);
}

.catalog-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 32px;
}

.grid-card {
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  border-radius: 16px;
  padding: 24px;
  transition: all 0.4s var(--ease-out-expo);
  position: relative;
  overflow: hidden;
}

.grid-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--neon-violet), var(--neon-cyan));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s var(--ease-out-expo);
}

.grid-card:hover {
  transform: translateY(-8px);
  border-color: var(--line-active);
  box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.8);
}

.grid-card:hover::before { transform: scaleX(1); }

.grid-cat {
