  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--txt-muted);
  margin-bottom: 12px;
}

.grid-title {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 12px;
  line-height: 1.3;
}

.grid-desc {
  font-size: 14px;
