  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.modal-btn:hover { background: rgba(255,255,255,0.1); border-color: var(--neon-violet); }

.modal-body {
  flex: 1;
  position: relative;
  background: #000;
}

.modal-body iframe {
  width: 100%;
  height: 100%;
  border: none;
}

.modal-fallback {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px;
  text-align: center;
  background: var(--bg-deep);
}

.fallback-icon {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: rgba(var(--glow-violet), 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  color: var(--neon-violet);
}

.fallback-title {
