  font-size: 24px;
  margin-bottom: 12px;
}

.fallback-desc {
  color: var(--txt-secondary);
  max-width: 400px;
  margin-bottom: 32px;
}

/* =========================================
   9. FOOTER & TOAST
   ========================================= */
.footer {
