const CATCOLOR={
  libros:"var(--violet)",
  musica:"var(--cyan)",
  videos:"var(--blue)",
  peliculas:"var(--red)",
  escuela:"#7ee787",
  cursos:"#ffb454",
  software:"#ff7ab6",
