<script>
"use strict";

// =========================================
// 1. UTILITIES & STATE
// =========================================
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const enc = q => encodeURIComponent(q);
const fmt = n => new Intl.NumberFormat('es-ES').format(n);

const state = {
  mode: 'max',
  sound: false,
  activeTab: 'all',
  modalUrl: '',
  audioCtx: null
};

const toast = (msg) => {
  const t = $('#toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 3000);
};

// =========================================
// 2. WEB AUDIO SYNTHESIZER
// =========================================
function initAudio() {
  if (!state.audioCtx) {
    state.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  }
  if (state.audioCtx.state === 'suspended') state.audioCtx.resume();
}

function playClick() {
  if (!state.sound) return;
  initAudio();
  const ctx = state.audioCtx;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(800, ctx.currentTime);
  osc.frequency.exponentialRampToValueAtTime(400, ctx.currentTime + 0.1);
  gain.gain.setValueAtTime(0.1, ctx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
  osc.connect(gain).connect(ctx.destination);
  osc.start();
  osc.stop(ctx.currentTime + 0.1);
}

function playHum() {
  if (!state.sound) return;
  initAudio();
  const ctx = state.audioCtx;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'sawtooth';
  osc.frequency.setValueAtTime(60, ctx.currentTime);
  osc.frequency.exponentialRampToValueAtTime(120, ctx.currentTime + 0.5);
  gain.gain.setValueAtTime(0.001, ctx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.05, ctx.currentTime + 0.2);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8);
  osc.connect(gain).connect(ctx.destination);
  osc.start();
  osc.stop(ctx.currentTime + 0.8);
}

// =========================================
// 3. CRT BOOT SEQUENCE
// =========================================
function runBoot() {
  const crt = $('#crt-boot');
  if (!crt) return;

  playHum();

  gsap.timeline()
    .to('.crt-beam', { scaleX: 1, opacity: 1, duration: 0.2, ease: 'power2.out' })
    .to('.crt-beam', { opacity: 0, duration: 0.1 })
    .to('.crt-expand', { scaleY: 1, opacity: 1, duration: 0.3, ease: 'power2.out' })
    .to('.crt-static', { opacity: 0.5, duration: 0.2 })
    .to('.crt-scanlines', { opacity: 1, duration: 0.2 }, '-=0.2')
    .to('.crt-logo', { opacity: 1, duration: 0.4, ease: 'power2.out' })
    .to('.crt-tube', { scale: 1.05, filter: 'brightness(1.5)', duration: 0.3 }, '+=0.5')
    .to('#crt-boot', { opacity: 0, duration: 0.5, ease: 'power2.in', onComplete: () => {
      crt.classList.add('off');
      document.body.classList.add('ready');
      initApp();
    }});
}

