const CAT_COLORS = {
  libros: '#7c3aed',
  ciencia: '#06b6d4',
  musica: '#ec4899',
  videos: '#3b82f6',
  peliculas: '#ef4444',
  escuela: '#10b981',
  cursos: '#f59e0b',
  software: '#8b5cf6',
  datos: '#14b8a6',
  arte: '#f43f5e'
};

// =========================================
// 5. UI RENDERING
// =========================================
function getGradient(cat, title) {
  const color = CAT_COLORS[cat] || '#7c3aed';
  const hash = title.split('').reduce((a, b) => (a << 5) - a + b.charCodeAt(0), 0);
  const angle = Math.abs(hash) % 360;
  return `linear-gradient(${angle}deg, ${color} 0%, #05050f 100%)`;
}

function renderStreamCards(trackId, items) {
  const track = $(`#${trackId}`);
  track.innerHTML = items.map(item => `
    <div class="stream-card" data-url="${item.url}" data-emb="${item.emb}" data-title="${item.title}">
      <div class="card-bg" style="background: ${getGradient(item.cat, item.title)}"></div>
      <div class="card-overlay">
        <div class="card-cat">${item.cat} · ${item.source}</div>
        <div class="card-title">${item.title}</div>
        <div class="card-desc">${item.desc}</div>
        <div class="card-actions">
          <button class="btn-play action-view">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>
            Ver
          </button>
          <button class="btn-info action-origin">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
          </button>
        </div>
      </div>
    </div>
  `).join('');

  track.querySelectorAll('.action-view').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const card = btn.closest('.stream-card');
      openViewer(card.dataset.url, card.dataset.title, card.dataset.emb === '1');
    });
  });

  track.querySelectorAll('.action-origin').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const card = btn.closest('.stream-card');
      window.open(card.dataset.url, '_blank');
    });
  });
}

function renderCatalogTabs() {
  const cats = ['all', ...new Set(CATALOG.map(i => i.cat))];
  const tabs = $('#catalog-tabs');
  tabs.innerHTML = cats.map(c => `
    <button class="cat-tab ${c === state.activeTab ? 'active' : ''}" data-cat="${c}">
      ${c === 'all' ? 'Todos' : c.charAt(0).toUpperCase() + c.slice(1)}
    </button>
  `).join('');

  tabs.querySelectorAll('.cat-tab').forEach(btn => {
    btn.addEventListener('click', () => {
      state.activeTab = btn.dataset.cat;
      renderCatalogTabs();
      renderCatalogGrid();
    });
  });
}

function renderCatalogGrid() {
  const items = state.activeTab === 'all' 
    ? CATALOG 
    : CATALOG.filter(i => i.cat === state.activeTab);

  const grid = $('#catalog-grid');
  grid.innerHTML = items.map(item => `
    <div class="grid-card" data-url="${item.url}" data-emb="${item.emb}" data-title="${item.title}">
      <div class="grid-cat">${item.cat} · ${item.source}</div>
      <div class="grid-title">${item.title}</div>
      <div class="grid-desc">${item.desc}</div>
      <div class="grid-meta">
        <span class="chip">Ver aquí</span>
        <span class="chip">Origen ↗</span>
      </div>
    </div>
  `).join('');

  grid.querySelectorAll('.grid-card').forEach(card => {
    card.addEventListener('click', (e) => {
      if (e.target.textContent.includes('Origen')) {
        window.open(card.dataset.url, '_blank');
      } else {
        openViewer(card.dataset.url, card.dataset.title, card.dataset.emb === '1');
      }
    });
  });
}

// =========================================
// 6. MODAL VIEWER
// =========================================
function openViewer(url, title, canEmbed) {
  state.modalUrl = url;
  $('#modal-title').textContent = title;
  const iframe = $('#modal-iframe');
  const fallback = $('#modal-fallback');

  if (canEmbed) {
    iframe.style.display = 'block';
    fallback.style.display = 'none';
    iframe.src = url;
  } else {
    iframe.style.display = 'none';
    iframe.src = 'about:blank';
    fallback.style.display = 'flex';
  }

  $('#modal-viewer').classList.add('open');
}

function closeViewer() {
  $('#modal-viewer').classList.remove('open');
  $('#modal-iframe').src = 'about:blank';
}

$('#modal-close').addEventListener('click', closeViewer);
$('#modal-origin').addEventListener('click', () => window.open(state.modalUrl, '_blank'));
$('#fallback-btn').addEventListener('click', () => window.open(state.modalUrl, '_blank'));
$('#modal-copy').addEventListener('click', () => {
  navigator.clipboard.writeText(state.modalUrl);
  toast('Enlace copiado al portapapeles');
});

$('#modal-viewer').addEventListener('click', (e) => {
  if (e.target === $('#modal-viewer')) closeViewer();
});

// =========================================
// 7. AI TERMINAL & TYPEWRITER
// =========================================
async function typeWriter(element, text, speed = 20) {
  element.innerHTML = '';
  for (let i = 0; i < text.length; i++) {
    element.innerHTML += text.charAt(i);
    await new Promise(r => setTimeout(r, speed));
  }
}

async function runAISynthesis(query) {
  const termInput = $('#term-input-display');
  const termOutput = $('#term-output');
  const termResults = $('#term-results');
  const cursor = $('#term-cursor');

  termInput.textContent = `analyze --federate "${query}"`;
  termOutput.innerHTML = '';
  termResults.innerHTML = '';
  termResults.classList.remove('visible');
  cursor.style.display = 'none';

  await new Promise(r => setTimeout(r, 500));

  await typeWriter(termOutput, `> Iniciando motor de inferencia local...\n`, 30);
  await new Promise(r => setTimeout(r, 300));
  await typeWriter(termOutput, `> Consultando ${BANKS.length} nodos federados vía CORS...\n`, 20);
  await new Promise(r => setTimeout(r, 400));

  const matches = CATALOG.filter(i => 
    i.title.toLowerCase().includes(query.toLowerCase()) || 
    i.desc.toLowerCase().includes(query.toLowerCase()) ||
    i.cat.toLowerCase().includes(query.toLowerCase())
  );

  const summary = matches.length > 0
    ? `> Análisis completado. Se encontraron ${matches.length} coincidencias de alta relevancia en el índice maestro. Recursos listos para inmersión inmediata.`
    : `> Análisis completado. No se encontraron coincidencias directas en el índice local, pero los nodos federados han sido alertados. Utilice los deep-links en el catálogo para buscar en las 140M+ fuentes externas.`;

  await typeWriter(termOutput, summary + '\n', 25);
  cursor.style.display = 'inline-block';

  if (matches.length > 0) {
    termResults.innerHTML = matches.slice(0, 4).map(item => `
      <div class="grid-card" data-url="${item.url}" data-emb="${item.emb}" data-title="${item.title}">
        <div class="grid-cat">${item.cat} · ${item.source}</div>
        <div class="grid-title">${item.title}</div>
        <div class="grid-desc">${item.desc}</div>
        <div class="grid-meta">
          <span class="chip action-view">Ver aquí</span>
          <span class="chip action-origin">Origen ↗</span>
        </div>
      </div>
    `).join('');

    termResults.classList.add('visible');

    termResults.querySelectorAll('.action-view').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const card = btn.closest('.grid-card');
        openViewer(card.dataset.url, card.dataset.title, card.dataset.emb === '1');
      });
    });

    termResults.querySelectorAll('.action-origin').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const card = btn.closest('.grid-card');
        window.open(card.dataset.url, '_blank');
      });
    });
  }
}

// =========================================
// 8. GSAP ANIMATIONS & SCROLL
// =========================================
function initAnimations() {
  gsap.registerPlugin(ScrollTrigger);

  // Header scroll effect
  ScrollTrigger.create({
    start: 'top -80',
    end: 99999,
    toggleClass: { className: 'scrolled', targets: '.header' }
  });

  // Hero text splitting and animation
  const title = $('.hero-title');
  const words = title.textContent.split(' ');
  title.innerHTML = words.map(w => `<span class="word">${w}</span>`).join(' ');

  const chars = [];
  title.querySelectorAll('.word').forEach(word => {
    const text = word.textContent;
    word.innerHTML = '';
    text.split('').forEach(c => {
      const span = document.createElement('span');
      span.className = 'char';
      span.textContent = c;
      word.appendChild(span);
      chars.push(span);
    });
  });

  gsap.timeline({ delay: 2.5 })
    .to('.hero-kicker', { opacity: 1, y: 0, duration: 0.8, ease: 'power3.out' })
    .to(chars, { y: 0, opacity: 1, duration: 0.8, stagger: 0.02, ease: 'power3.out' }, '-=0.4')
    .to('.hero-sub', { opacity: 1, y: 0, duration: 0.8, ease: 'power3.out' }, '-=0.4')
    .to('.hero-search', { opacity: 1, y: 0, duration: 0.8, ease: 'power3.out' }, '-=0.4')
    .to('.hero-stats', { opacity: 1, y: 0, duration: 0.8, ease: 'power3.out' }, '-=0.4');

  // Parallax orbs
  gsap.to('.orb-1', { y: () => innerHeight * 0.3, ease: 'none', scrollTrigger: { scrub: true } });
  gsap.to('.orb-2', { y: () => innerHeight * 0.15, ease: 'none', scrollTrigger: { scrub: true } });
  gsap.to('.orb-3', { y: () => -innerHeight * 0.2, ease: 'none', scrollTrigger: { scrub: true } });

  // Section reveals
  gsap.utils.toArray('.sec-header, .ai-terminal, .catalog-tabs, .catalog-grid').forEach(el => {
    gsap.from(el, {
      y: 40,
      opacity: 0,
      duration: 1,
      ease: 'power3.out',
      scrollTrigger: { trigger: el, start: 'top 85%' }
    });
  });
}

// =========================================
// 9. EVENT LISTENERS & INIT
// =========================================
function initApp() {
  // Render UI
  renderStreamCards('stream-track-1', CATALOG.filter(i => ['libros', 'peliculas', 'musica', 'arte'].includes(i.cat)).slice(0, 12));
  renderStreamCards('stream-track-2', CATALOG.filter(i => ['ciencia', 'datos', 'videos', 'escuela'].includes(i.cat)).slice(0, 12));
  renderCatalogTabs();
  renderCatalogGrid();

  // Stats counter
  $('#stat-sources').textContent = CATALOG.length + BANKS.length;

  // Event listeners
  $('#btn-sound').addEventListener('click', () => {
    state.sound = !state.sound;
    if (state.sound) {
      initAudio();
      playClick();
      toast('Audio sintetizado activado');
    } else {
      toast('Audio desactivado');
    }
  });

  $('#btn-theme').addEventListener('click', () => {
    toast('Tema OLED optimizado para contraste infinito');
  });

  // Carousel navigation
  $$('.stream-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const dir = parseInt(btn.dataset.dir);
      const track = btn.closest('.section-stream').querySelector('.stream-track');
      track.scrollBy({ left: dir * 600, behavior: 'smooth' });
    });
  });

  // AI Terminal search
  $('#hero-search-btn').addEventListener('click', () => {
    const query = $('#hero-input').value.trim();
    if (query) {
      $('#ai-section').scrollIntoView({ behavior: 'smooth' });
      setTimeout(() => runAISynthesis(query), 800);
    }
  });

  $('#hero-input').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      $('#hero-search-btn').click();
    }
  });

  // Global shortcuts
  document.addEventListener('keydown', (e) => {
    if (e.key === '/' && document.activeElement.tagName !== 'INPUT') {
      e.preventDefault();
      $('#hero-input').focus();
    }
    if (e.key === 'Escape') {
      closeViewer();
    }
  });

  // Init animations
  initAnimations();
}

// Start Boot Sequence
window.addEventListener('DOMContentLoaded', runBoot);
</script>
</body>
</html>
